//! Item ID -> creation date, from the fitted timeline in `timeline_data.rs`
//! (generated by `scripts/fit_item_id_timeline.py`).

use super::timeline_data::{KNOTS, RECENT_IDS_PER_SEC};

const DAY: i64 = 86400;
/// Half width of a date read off the timeline. Item creation is not linear (Halloween contracts,
/// Smissmas gifts, case releases nearly double the daily growth); the daily knots follow that, and
/// the held-out error of genuine items has a p99 of 1.4-1.9 days in every year since 2013 (weekly
/// knots before 2024-11), so 2 days covers it.
const UNCERTAINTY_SECS: i64 = 2 * DAY;
/// Extrapolation error grows with the distance from the timeline: item creation varies with
/// events and updates (Halloween, Smissmas, case drops).
const EXTRAPOLATION_ERROR_PER_SEC: f64 = 0.15;

/// A date derived from an item ID.
#[derive(Debug, Clone, Copy)]
pub struct IdDate {
    pub timestamp: i64,
    /// Half width of the uncertainty.
    pub uncertainty_secs: i64,
    /// Outside the fitted timeline (newer than the last demo it was fitted on).
    pub extrapolated: bool,
}

/// The last date the timeline has data for; newer item IDs are extrapolated.
pub const TIMELINE_LAST_DATE: i64 = KNOTS[KNOTS.len() - 1].0;

/// When an item ID was created.
pub fn date_of_item_id(id: u64) -> IdDate {
    let base = UNCERTAINTY_SECS;
    let (first_t, first_id) = KNOTS[0];
    let (last_t, last_id) = KNOTS[KNOTS.len() - 1];
    if id >= last_id {
        let ahead = ((id - last_id) as f64 / RECENT_IDS_PER_SEC) as i64;
        return IdDate {
            timestamp: last_t + ahead,
            uncertainty_secs: base + (ahead as f64 * EXTRAPOLATION_ERROR_PER_SEC) as i64,
            extrapolated: id > last_id,
        };
    }
    if id <= first_id {
        // Older than the timeline (before 2014): extrapolate back with the first year's growth
        let year_end = KNOTS.iter().find(|(t, _)| *t >= first_t + 365 * DAY).unwrap_or(&KNOTS[KNOTS.len() - 1]);
        let rate = (year_end.1 - first_id) as f64 / (year_end.0 - first_t).max(1) as f64;
        let behind = ((first_id - id) as f64 / rate.max(1.0)) as i64;
        return IdDate {
            timestamp: first_t - behind,
            uncertainty_secs: base + (behind as f64 * EXTRAPOLATION_ERROR_PER_SEC) as i64,
            extrapolated: true,
        };
    }
    let k = KNOTS.partition_point(|(_, kid)| *kid <= id);
    let (t0, i0) = KNOTS[k - 1];
    let (t1, i1) = KNOTS[k];
    let timestamp = t0 + ((t1 - t0) as f64 * (id - i0) as f64 / (i1 - i0) as f64) as i64;
    IdDate { timestamp, uncertainty_secs: base, extrapolated: false }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn knots_are_increasing() {
        for w in KNOTS.windows(2) {
            assert!(w[0].0 < w[1].0 && w[0].1 < w[1].1, "{:?}", w);
        }
    }

    #[test]
    fn interpolation_is_monotone_and_hits_knots() {
        let (t, id) = KNOTS[KNOTS.len() / 2];
        assert!((date_of_item_id(id).timestamp - t).abs() <= 1);
        let mut last = i64::MIN;
        for (_, id) in KNOTS.iter().step_by(37) {
            let d = date_of_item_id(*id + 1);
            assert!(d.timestamp >= last);
            last = d.timestamp;
        }
    }

    #[test]
    fn extrapolates_past_the_end() {
        let (t, id) = KNOTS[KNOTS.len() - 1];
        let d = date_of_item_id(id + (RECENT_IDS_PER_SEC * 10.0 * DAY as f64) as u64);
        assert!(d.extrapolated);
        assert!((d.timestamp - (t + 10 * DAY)).abs() < DAY);
        assert!(d.uncertainty_secs > date_of_item_id(id - 1).uncertainty_secs);
    }
}
